import{_ as t,H as p,f as a,i as r}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"05 | [视频]opm项目导读","description":"","frontmatter":{},"headers":[{"level":2,"title":"今日核心","slug":"今日核心","link":"#今日核心","children":[]},{"level":2,"title":"课件参考","slug":"课件参考","link":"#课件参考","children":[]}],"relativePath":"OpenResty从入门到实战/05-［视频］opm项目导读.md","filePath":"OpenResty从入门到实战/05-［视频］opm项目导读.md","lastUpdated":1780767177000}'),o={name:"OpenResty从入门到实战/05-［视频］opm项目导读.md"};function n(s,e,i,l,_,h){return p(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_05-视频-opm项目导读" tabindex="-1">05 | [视频]opm项目导读 <a class="header-anchor" href="#_05-视频-opm项目导读" aria-label="Permalink to &quot;05 | [视频]opm项目导读&quot;">​</a></h1><p>你好，我是温铭。</p><p>今天的内容，我特意安排成了视频的形式来讲解。不过，在你看视频之前，我想先问你这么几个问题：</p><ul><li>在真实的项目中，你会配置 nginx.conf，以便和 Lua 代码联动吗？</li><li>你清楚 OpenResty 的代码结构该如何组织吗？</li></ul><p>这两个问题，也是今天视频课要解决的核心内容，希望你可以先自己思考一下，并带着问题来学习今天的视频内容。</p><p>同时，我会给出相应的文字介绍，方便你在听完视频内容后，及时总结与复习。下面是今天这节课的文字介绍部分。</p><h2 id="今日核心" tabindex="-1">今日核心 <a class="header-anchor" href="#今日核心" aria-label="Permalink to &quot;今日核心&quot;">​</a></h2><p><a href="https://github.com/openresty/opm/" target="_blank" rel="noreferrer">opm</a> 是 OpenResty 中为数不多的网站类项目，而里面的代码，基本上是由 OpenResty 的作者亲自操刀完成的。</p><p>很多 OpenResty 的使用者并不清楚，如何在真实的项目中去配置 nginx.conf， 以及如何组织 Lua 的代码结构。确实，在这方面可以参考的开源项目并不多，给学习使用带了不小的阻力。</p><p>不过，借助今天的这个项目，你就可以克服这一点了。你将会熟悉一个OpenResty 项目的结构和开发流程，还能看到 OpenResty 的作者是如何编写业务类 Lua 代码的。</p><p>opm 还涉及到数据库的操作，它后台数据的储存，使用的是PostgreSQL ，你可以顺便了解下 OpenResty 和数据库是如何交互的。</p><p>除此之外，这个项目还涉及到一些简单的性能优化，也是为了后面专门设立的性能优化内容做个铺垫。</p><p>最后，浏览完 opm 这个项目后，你可以自行看下另外一个类似的项目，那就是 OpenResty 的官方网站： <a href="https://github.com/openresty/openresty.org" target="_blank" rel="noreferrer">https://github.com/openresty/openresty.org</a>。</p><h2 id="课件参考" tabindex="-1">课件参考 <a class="header-anchor" href="#课件参考" aria-label="Permalink to &quot;课件参考&quot;">​</a></h2><p>今天的课件已经上传到了我的GitHub上，你可以自己下载学习。</p><p>链接如下： <a href="https://github.com/iresty/geektime-slides" target="_blank" rel="noreferrer">https://github.com/iresty/geektime-slides</a></p><p>如果有不清楚的地方，你可以在留言区提问，另也可以在留言区分享你的学习心得。期待与你的对话，也欢迎你把这篇文章分享给你的同事、朋友，我们一起交流、一起进步。</p>',17)])])}const d=t(o,[["render",n]]);export{c as __pageData,d as default};
